'use client';

import * as React from 'react';
import Link from 'next/link';
import { useRouter } from 'next/navigation';
import { useForm } from 'react-hook-form';
import { Building2, CheckCircle2, LayoutDashboard, LogOut, Package, Plus, ShieldCheck, ShoppingBag, Store, Trash2 } from 'lucide-react';
import { Button } from '@/components/ui/Button';
import { Card } from '@/components/ui/Card';
import { Input } from '@/components/ui/Input';
import { Badge } from '@/components/ui/Badge';
import { toast } from '@/components/ui/Toast';
import { GlobalLayout } from '@/components/layout/GlobalLayout';
import { useAuth } from '@/lib/providers/AuthProvider';
import { api } from '@/lib/api';
import { formatINR } from '@/utils/format';

type BackendProduct = { id: number; name: string; slug: string; sku: string; price: string; final_price: string; stock: number; status: string; images: Array<{ image: string; alt_text: string }> };
type ProductResponse = { count: number; results: BackendProduct[] };
type BackendOrder = { id: number; order_number: string; total_amount: string; status: string; created_at: string; items: Array<{ product_name: string; vendor_name: string; quantity: number; unit_price: string; total_price: string }> };
type OrderResponse = { count: number; results: BackendOrder[] };
const token = () => typeof window === 'undefined' ? '' : localStorage.getItem('electrohub_access_token') ?? '';

function Guard({ children }: { children: React.ReactNode }) { const router = useRouter(); const { user, isLoggedIn } = useAuth(); const allowed = isLoggedIn && user?.role === 'vendor'; React.useEffect(() => { if (!isLoggedIn) router.replace('/login'); else if (user?.role !== 'vendor') router.replace('/'); }, [isLoggedIn, router, user?.role]); if (!allowed) return <GlobalLayout><div className="container-fluid py-24 text-center"><ShieldCheck className="mx-auto mb-4 text-[var(--primary)]" size={36} /><h1 className="text-2xl font-bold text-[var(--text)]">Vendor access required</h1></div></GlobalLayout>; return <>{children}</>; }
function Shell({ children, active }: { children: React.ReactNode; active: string }) { const { user, logout } = useAuth(); const links = [['Dashboard','/vendor/dashboard',LayoutDashboard],['My Products','/vendor/products',Package],['Add Product','/vendor/products/add',Plus],['Orders','/vendor/orders',ShoppingBag],['Business Profile','/vendor/profile',Building2]] as const; return <GlobalLayout><div className="container-fluid py-8"><div className="mb-7 flex items-end justify-between"><div><p className="text-xs font-semibold uppercase tracking-[0.18em] text-[var(--primary)]">Marketplace workspace</p><h1 className="mt-1 text-2xl font-bold font-display text-[var(--text)]">{active === 'Dashboard' ? `Welcome, ${user?.name?.split(' ')[0] ?? 'Vendor'}` : active}</h1></div><Button variant="ghost" size="sm" onClick={logout} leftIcon={<LogOut size={14} />}>Logout</Button></div><div className="grid gap-6 lg:grid-cols-[220px_minmax(0,1fr)]"><aside className="h-fit rounded-2xl border border-[var(--border)] bg-[var(--background-card)] p-3"><div className="mb-3 flex items-center gap-3 rounded-xl bg-[var(--surface)] p-3"><Store size={18} className="text-[var(--primary)]" /><p className="text-sm font-semibold text-[var(--text)]">Vendor workspace</p></div><nav className="space-y-1">{links.map(([label,href,Icon]) => <Link key={href} href={href} className={`flex items-center gap-3 rounded-xl px-3 py-2.5 text-sm ${active === label ? 'bg-[var(--primary)]/10 text-[var(--primary)] font-semibold' : 'text-[var(--text-muted)] hover:bg-[var(--surface-hover)]'}`}><Icon size={15} />{label}</Link>)}</nav></aside><main>{children}</main></div></div></GlobalLayout>; }

function useVendorData() { const [products,setProducts] = React.useState<BackendProduct[]>([]); const [orders,setOrders] = React.useState<BackendOrder[]>([]); const [error,setError] = React.useState(''); React.useEffect(() => { Promise.all([api.get<ProductResponse>('/products/vendor/',{token:token()}),api.get<OrderResponse>('/orders/vendor/',{token:token()})]).then(([p,o]) => { setProducts(p.results); setOrders(o.results); }).catch((e) => setError(e instanceof Error ? e.message : 'Unable to load vendor data.')); }, []); return { products, orders, error, setProducts, setOrders }; }

export function RealVendorDashboard() { const { products, orders, error } = useVendorData(); const stats: Array<{ label: string; value: string | number; icon: React.ElementType }> = [{ label: 'Total Products', value: products.length, icon: Package }, { label: 'Active Products', value: products.filter(p=>p.status==='active').length, icon: CheckCircle2 }, { label: 'Orders', value: orders.length, icon: ShoppingBag }, { label: 'Sales', value: formatINR(orders.reduce((s,o)=>s+Number(o.total_amount),0)), icon: ShoppingBag }]; return <Guard><Shell active="Dashboard"><p className="mb-5 text-sm text-[var(--danger)]">{error}</p><div className="grid gap-4 sm:grid-cols-2 xl:grid-cols-4">{stats.map(({ label, value, icon: Icon }) => <Card key={label} className="p-5"><Icon size={18} className="text-[var(--primary)]" /><p className="mt-4 text-sm text-[var(--text-muted)]">{label}</p><p className="mt-1 text-2xl font-bold text-[var(--text)]">{value}</p></Card>)}</div></Shell></Guard>; }

export function RealVendorProducts({ add = false }: { add?: boolean }) { return <Guard><Shell active={add ? 'Add Product' : 'My Products'}>{add ? <RealAddProduct /> : <RealProductList />}</Shell></Guard>; }
function RealProductList() { const { products, error, setProducts } = useVendorData(); const remove = async (product: BackendProduct) => { try { await api.delete(`/products/${product.slug}/`,{token:token()}); setProducts(products.filter(p=>p.id!==product.id)); toast.success('Product deactivated'); } catch(e) { toast.error(e instanceof Error ? e.message : 'Unable to deactivate product.'); } }; return <div><div className="mb-5 flex items-center justify-between"><div><h2 className="text-xl font-bold text-[var(--text)]">My Products</h2><p className="mt-1 text-sm text-[var(--text-muted)]">Loaded from the Django catalogue.</p></div><Link href="/vendor/products/add"><Button size="sm" leftIcon={<Plus size={14} />}>Add Product</Button></Link></div>{error && <p className="mb-4 text-sm text-[var(--danger)]">{error}</p>}<Card className="overflow-hidden"><div className="divide-y divide-[var(--border)]">{products.map(p=><div key={p.id} className="flex flex-wrap items-center gap-4 p-4"><img src={p.images[0]?.image} alt={p.images[0]?.alt_text ?? p.name} className="h-14 w-14 rounded-lg bg-[var(--background-alt)] object-contain p-1" /><div className="min-w-[180px] flex-1"><p className="font-semibold text-[var(--text)]">{p.name}</p><p className="mt-1 text-xs text-[var(--text-muted)]">SKU: {p.sku}</p></div><span className="font-semibold text-[var(--text)]">{formatINR(Number(p.final_price))}</span><span className="text-sm text-[var(--text-muted)]">Stock: {p.stock}</span><Badge variant={p.status==='active'?'success':'default'}>{p.status}</Badge><button onClick={()=>remove(p)} className="text-[var(--danger)]" aria-label={`Delete ${p.name}`}><Trash2 size={15}/></button></div>)}</div></Card></div>; }
interface AddForm { name:string; category_name:string; brand_name:string; sku:string; price:string; stock:string; short_description:string; description:string; }
function RealAddProduct() { const router=useRouter(); const {register,handleSubmit,formState:{errors,isSubmitting}}=useForm<AddForm>(); const submit=async(data:AddForm)=>{try{await api.post('/products/',{...data,price:data.price,discount_price:data.price,slug:`${data.sku.toLowerCase().replace(/[^a-z0-9]+/g,'-')}-${crypto.randomUUID().slice(0,8)}`},{token:token()});toast.success('Product saved to Django');router.push('/vendor/products');}catch(e){toast.error(e instanceof Error?e.message:'Unable to save product.');}}; return <Card className="max-w-3xl p-6"><h2 className="text-xl font-bold text-[var(--text)]">Add Product</h2><p className="mt-1 mb-6 text-sm text-[var(--text-muted)]">This product is saved to the Django database.</p><form onSubmit={handleSubmit(submit)} className="grid gap-4 sm:grid-cols-2">{[['name','Product Name'],['category_name','Category'],['brand_name','Brand'],['sku','SKU'],['price','Price'],['stock','Stock'],['short_description','Short Description'],['description','Description']].map(([name,label])=><Input key={name} label={label} type={name==='price'||name==='stock'?'number':'text'} error={errors[name as keyof AddForm]?.message} {...register(name as keyof AddForm,{required:`${label} is required`})}/>)}<div className="sm:col-span-2"><Button type="submit" isLoading={isSubmitting} leftIcon={<Plus size={15}/>}>Save Product</Button></div></form></Card>; }

export function RealVendorOrders() { const { orders, error, setOrders } = useVendorData(); return <Guard><Shell active="Orders"><h2 className="mb-5 text-xl font-bold text-[var(--text)]">Orders</h2>{error&&<p className="mb-4 text-sm text-[var(--danger)]">{error}</p>}<Card className="overflow-hidden"><div className="divide-y divide-[var(--border)]">{orders.map(o=><div key={o.id} className="p-4"><div className="flex flex-wrap items-center justify-between gap-3"><div><p className="font-semibold text-[var(--text)]">Order #{o.order_number}</p><p className="text-xs text-[var(--text-muted)]">{new Date(o.created_at).toLocaleDateString('en-IN')}</p></div><select value={o.status} onChange={async (event) => { try { const updated = await api.patch<BackendOrder>(`/orders/vendor/${o.id}/status/`, { status: event.target.value }, { token: token() }); setOrders((current) => current.map((order) => order.id === o.id ? updated : order)); toast.success('Order status updated'); } catch (statusError) { toast.error(statusError instanceof Error ? statusError.message : 'Unable to update order status.'); } }} className="rounded-lg border border-[var(--border)] bg-[var(--background-card)] px-2 py-1.5 text-xs text-[var(--text)]"><option value="pending">Pending</option><option value="processing">Processing</option><option value="shipped">Shipped</option><option value="completed">Completed</option><option value="cancelled">Cancelled</option></select><span className="font-semibold text-[var(--text)]">{formatINR(Number(o.total_amount))}</span></div>{o.items.map((item,index)=><p key={`${o.id}-${index}`} className="mt-2 text-sm text-[var(--text-muted)]">{item.product_name} × {item.quantity} · {formatINR(Number(item.total_price))}</p>)}</div>)}</div></Card></Shell></Guard>; }
